import { useState, useEffect } from 'react';
import { supabase } from '../lib/supabaseClient';
import type { Convidado } from '../types';
import { Users, UserMinus, Clock, Search, Lock, Trash2, Eye, X, Network } from 'lucide-react';
import { AdminFamilyTree } from './FamilyTree/AdminFamilyTree';

export const Dashboard = () => {
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [password, setPassword] = useState('');
    const [convidados, setConvidados] = useState<Convidado[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedMessage, setSelectedMessage] = useState<Convidado | null>(null);
    const [activeTab, setActiveTab] = useState<'rsvp' | 'tree'>('rsvp');

    // Simple hardcoded password for demo purposes
    const ADMIN_PASSWORD = "maria90anos";

    useEffect(() => {
        if (isAuthenticated) {
            fetchConvidados();
        }
    }, [isAuthenticated]);

    const fetchConvidados = async () => {
        setLoading(true);
        const { data, error } = await supabase
            .from('convidados')
            .select('*')
            .order('created_at', { ascending: false });

        if (error) {
            console.error('Error fetching data:', error);
        } else {
            setConvidados(data || []);
        }
        setLoading(false);
    };

    const handleLogin = (e: React.FormEvent) => {
        e.preventDefault();
        if (password === ADMIN_PASSWORD) {
            setIsAuthenticated(true);
        } else {
            alert("Senha incorreta");
        }
    };

    const handleDelete = async (id: string) => {
        if (!window.confirm("Tem certeza que deseja remover este convidado?")) return;

        const { error } = await supabase
            .from('convidados')
            .delete()
            .eq('id', id);

        if (error) {
            console.error('Erro ao deletar:', error);
            alert("Erro ao excluir convidado.");
        } else {
            setConvidados(prev => prev.filter(c => c.id !== id));
        }
    };

    if (!isAuthenticated) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[50vh] p-4">
                <div className="bg-white p-8 rounded-xl shadow-lg border border-gray-100 w-full max-w-md">
                    <div className="flex justify-center mb-4 text-rosa-forte">
                        <Lock size={32} />
                    </div>
                    <h2 className="text-2xl font-serif text-center mb-6 text-gray-800">Acesso Restrito</h2>
                    <form onSubmit={handleLogin} className="space-y-4">
                        <input
                            type="password"
                            placeholder="Senha de administrador"
                            className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-rosa-antigo focus:border-transparent outline-none"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                        />
                        <button
                            type="submit"
                            className="w-full bg-rosa-forte text-white py-2 rounded-lg hover:bg-rosa-antigo transition-colors"
                        >
                            Entrar
                        </button>
                    </form>
                </div>
            </div>
        );
    }

    const confirmados = convidados.filter(c => c.vai_comparecer);
    const recusados = convidados.filter(c => !c.vai_comparecer);

    const totalConfirmados = confirmados.reduce((acc, curr) => acc + 1 + (curr.qtd_acompanhantes || 0), 0);
    const totalTitulares = confirmados.length;

    const filteredConvidados = convidados.filter(c =>
        c.nome_completo.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="p-4 md:p-8 max-w-7xl mx-auto">
            <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                <h1 className="text-3xl font-serif text-rosa-forte">Painel Administrativo</h1>
                <div className="flex gap-2 bg-gray-100 p-1 rounded-lg">
                    <button
                        onClick={() => setActiveTab('rsvp')}
                        className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'rsvp'
                            ? 'bg-white text-gray-800 shadow-sm'
                            : 'text-gray-500 hover:text-gray-700'
                            }`}
                    >
                        Gest├úo de Convites
                    </button>
                    <button
                        onClick={() => setActiveTab('tree')}
                        className={`px-4 py-2 rounded-md text-sm font-medium transition-all flex items-center gap-2 ${activeTab === 'tree'
                            ? 'bg-white text-gray-800 shadow-sm'
                            : 'text-gray-500 hover:text-gray-700'
                            }`}
                    >
                        <Network size={16} />
                        ├ürvore Geneal├│gica
                    </button>
                </div>
            </div>

            {activeTab === 'tree' ? (
                <AdminFamilyTree />
            ) : (
                <>
                    <div className="flex justify-end mb-6">
                        <button
                            onClick={fetchConvidados}
                            className="text-sm text-gray-500 hover:text-rosa-forte flex items-center gap-2"
                        >
                            <Clock size={16} /> Atualizar Lista
                        </button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                            <div className="flex items-center gap-4">
                                <div className="p-3 bg-green-100 text-green-600 rounded-full">
                                    <Users size={24} />
                                </div>
                                <div>
                                    <p className="text-sm text-gray-500">Total Confirmados</p>
                                    <h3 className="text-2xl font-bold text-gray-800">{totalConfirmados}</h3>
                                    <p className="text-xs text-gray-400">({totalTitulares} convites)</p>
                                </div>
                            </div>
                        </div>

                        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                            <div className="flex items-center gap-4">
                                <div className="p-3 bg-red-100 text-red-600 rounded-full">
                                    <UserMinus size={24} />
                                </div>
                                <div>
                                    <p className="text-sm text-gray-500">Recusas</p>
                                    <h3 className="text-2xl font-bold text-gray-800">{recusados.length}</h3>
                                </div>
                            </div>
                        </div>

                        {/* Placeholder for Average Age calculation if desired later */}
                    </div>

                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                        <div className="p-4 border-b border-gray-100 flex items-center justify-between gap-4 flex-wrap">
                            <h2 className="font-semibold text-gray-700">Lista de Convidados</h2>
                            <div className="relative">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                                <input
                                    type="text"
                                    placeholder="Buscar nome..."
                                    className="pl-9 pr-4 py-1.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:border-rosa-antigo"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                />
                            </div>
                        </div>

                        <div className="overflow-x-auto">
                            <table className="w-full text-left text-sm">
                                <thead className="bg-gray-50 text-gray-600 font-medium border-b border-gray-100">
                                    <tr>
                                        <th className="px-6 py-3">Nome</th>
                                        <th className="px-6 py-3">Idade</th>
                                        <th className="px-6 py-3">Status</th>
                                        <th className="px-6 py-3">Acompanhantes</th>
                                        <th className="px-6 py-3">Mensagem</th>
                                        <th className="px-6 py-3">A├º├Áes</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {loading ? (
                                        <tr><td colSpan={6} className="px-6 py-8 text-center text-gray-500">Carregando...</td></tr>
                                    ) : filteredConvidados.map((c) => (
                                        <tr key={c.id} className="hover:bg-gray-50 transition-colors">
                                            <td className="px-6 py-3 font-medium text-gray-900">{c.nome_completo}</td>
                                            <td className="px-6 py-3 text-gray-500">{c.idade}</td>
                                            <td className="px-6 py-3">
                                                <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${c.vai_comparecer
                                                    ? 'bg-green-100 text-green-800'
                                                    : 'bg-red-100 text-red-800'
                                                    }`}>
                                                    {c.vai_comparecer ? 'Confirmado' : 'Recusado'}
                                                </span>
                                            </td>
                                            <td className="px-6 py-3 text-gray-500">
                                                {c.vai_comparecer ? (
                                                    <div>
                                                        <span className="font-medium">{c.qtd_acompanhantes}</span>
                                                        {c.nomes_acompanhantes && <p className="text-xs text-gray-400 truncate max-w-[150px]">{c.nomes_acompanhantes}</p>}
                                                    </div>
                                                ) : '-'}
                                            </td>
                                            <td className="px-6 py-3 text-gray-500 max-w-xs relative group cursor-default">
                                                {c.mensagem_justificativa ? (
                                                    <div
                                                        onClick={() => setSelectedMessage(c)}
                                                        className="flex items-center gap-2 cursor-pointer hover:bg-gray-100/80 p-1.5 -ml-1.5 rounded-lg transition-all"
                                                        title="Clique para ler a mensagem completa"
                                                    >
                                                        <p className="truncate flex-1 font-normal group-hover:text-gray-800 transition-colors">
                                                            {c.mensagem_justificativa}
                                                        </p>
                                                        <Eye
                                                            size={16}
                                                            className="text-gray-400 opacity-0 group-hover:opacity-100 group-hover:text-rosa-forte transition-all shrink-0 translate-x-1 group-hover:translate-x-0"
                                                        />
                                                    </div>
                                                ) : (
                                                    <span className="text-gray-300 text-xs italic">-</span>
                                                )}
                                            </td>
                                            <td className="px-6 py-3">
                                                <button
                                                    onClick={() => handleDelete(c.id)}
                                                    className="p-1 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                                    title="Excluir"
                                                >
                                                    <Trash2 size={18} />
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                    {!loading && filteredConvidados.length === 0 && (
                                        <tr><td colSpan={6} className="px-6 py-8 text-center text-gray-500">Nenhum registro encontrado.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>

                    {/* Message Modal */}
                    {selectedMessage && (
                        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-300">
                            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-300 scale-100 border border-gray-100">
                                {/* Header */}
                                <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                                    <div>
                                        <h3 className="font-serif text-xl text-gray-800">Mensagem de {selectedMessage.nome_completo.split(' ')[0]}</h3>
                                        {selectedMessage.created_at && (
                                            <span className="text-xs text-gray-400 font-medium tracking-wide uppercase mt-1 block">
                                                Enviada em {new Date(selectedMessage.created_at).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })}
                                            </span>
                                        )}
                                    </div>
                                    <button
                                        onClick={() => setSelectedMessage(null)}
                                        className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"
                                    >
                                        <X size={20} />
                                    </button>
                                </div>

                                {/* Body */}
                                <div className="p-6 max-h-[60vh] overflow-y-auto custom-scrollbar">
                                    <div className="bg-stone-50 p-4 rounded-xl border border-stone-100">
                                        <p className="text-gray-700 leading-relaxed whitespace-pre-wrap font-sans text-base">
                                            {selectedMessage.mensagem_justificativa}
                                        </p>
                                    </div>
                                </div>

                                {/* Footer */}
                                <div className="p-4 border-t border-gray-100 bg-gray-50/50 flex justify-end">
                                    <button
                                        onClick={() => setSelectedMessage(null)}
                                        className="px-5 py-2 bg-white hover:bg-gray-50 border border-gray-200 text-gray-700 rounded-lg text-sm font-medium transition-all shadow-sm hover:shadow"
                                    >
                                        Fechar leitura
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                </>
            )}
        </div>
    );
};

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../../lib/supabaseClient';
import type { FamilyMember } from '../../types';
import { Loader2, Upload, X, Instagram, Facebook, Phone, Crop as CropIcon, Check } from 'lucide-react';
import Cropper from 'react-easy-crop';
import getCroppedImg from '../../utils/cropImage';

interface MemberFormProps {
    member?: FamilyMember | null;
    onSuccess: () => void;
    onCancel: () => void;
    existingMembers: FamilyMember[];
}

export const MemberForm = ({ member, onSuccess, onCancel, existingMembers }: MemberFormProps) => {
    const [loading, setLoading] = useState(false);

    // Form States
    const [name, setName] = useState(member?.name || '');
    const [parentId, setParentId] = useState(member?.parent_id || '');
    const [description, setDescription] = useState(member?.description || '');
    // const [birthOrder, setBirthOrder] = useState(member?.birth_order?.toString() || '0'); // Deprecated
    const [birthDate, setBirthDate] = useState(member?.birth_date || '');
    const [isDeceased, setIsDeceased] = useState(member?.is_deceased || false);
    const [deathDate, setDeathDate] = useState(member?.death_date || '');
    const [role, setRole] = useState<'patriarca' | 'matriarca' | 'descendente'>(member?.role || 'descendente');

    const [instagram, setInstagram] = useState(member?.social_links?.instagram || '');
    const [whatsapp, setWhatsapp] = useState(member?.social_links?.whatsapp || '');
    const [facebook, setFacebook] = useState(member?.social_links?.facebook || '');
    const [photoUrl, setPhotoUrl] = useState(member?.photo_url || '');

    // Image Upload & Crop States
    const [uploading, setUploading] = useState(false);
    const [uploadError, setUploadError] = useState('');
    const [selectedImage, setSelectedImage] = useState<string | null>(null);
    const [isCropModalOpen, setIsCropModalOpen] = useState(false);
    const [crop, setCrop] = useState({ x: 0, y: 0 });
    const [zoom, setZoom] = useState(1);
    const [croppedAreaPixels, setCroppedAreaPixels] = useState<any>(null);

    // Initial Load
    useEffect(() => {
        if (member) {
            setName(member.name);
            setParentId(member.parent_id || '');
            setDescription(member.description || '');
            setBirthDate(member.birth_date || '');
            setIsDeceased(member.is_deceased || false);
            setDeathDate(member.death_date || '');
            setRole(member.role || 'descendente');
            setInstagram(member.social_links?.instagram || '');
            setWhatsapp(member.social_links?.whatsapp || '');
            setFacebook(member.social_links?.facebook || '');
            setPhotoUrl(member.photo_url || '');
        }
    }, [member]);

    // Handle File Selection
    const onFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            const file = e.target.files[0];
            const imageDataUrl = await readFile(file);
            setSelectedImage(imageDataUrl as string);
            setIsCropModalOpen(true);
            setUploadError('');
            // Reset input value to allow re-selecting same file if needed
            e.target.value = '';
        }
    };

    const readFile = (file: File) => {
        return new Promise((resolve) => {
            const reader = new FileReader();
            reader.addEventListener('load', () => resolve(reader.result));
            reader.readAsDataURL(file);
        });
    };

    const onCropComplete = useCallback((_: any, croppedAreaPixels: any) => {
        setCroppedAreaPixels(croppedAreaPixels);
    }, []);

    const handleCancelCrop = () => {
        setIsCropModalOpen(false);
        setSelectedImage(null);
        setUploadError('');
        // Reset file input if needed is handled by finding the input element, but easier to just leave it as React state is cleared.
    };

    // Execute Crop & Upload
    const handleCropSave = async () => {
        if (!selectedImage || !croppedAreaPixels) return;

        try {
            setUploading(true);
            setUploadError('');

            // 1. Generate Blob from Crop
            const croppedBlob = await getCroppedImg(selectedImage, croppedAreaPixels);

            // 2. Prepare File Path
            // Organized structure: members/{uuid}/{timestamp}.jpg
            // NOTE: For new users, we don't have an ID yet. Using random string structure.
            const fileExt = 'jpg';
            const fileName = `member-${Date.now()}-${Math.random().toString(36).substring(2, 9)}.${fileExt}`;
            const filePath = `members/${fileName}`;

            // 3. Delete OLD image if exists (Garbage Collection)
            if (photoUrl) {
                const oldPath = photoUrl.split('/family-photos/')[1];
                if (oldPath) {
                    await supabase.storage.from('family-photos').remove([oldPath]);
                }
            }

            // 4. Upload NEW image
            const { error: uploadErr } = await supabase.storage
                .from('family-photos')
                .upload(filePath, croppedBlob, {
                    contentType: 'image/jpeg',
                    cacheControl: '3600',
                    upsert: false
                });

            if (uploadErr) {
                // Check specifically for "Bucket not found"
                if (uploadErr.message.includes('Bucket not found') || (uploadErr as any).statusCode === '404') {
                    throw new Error('Erro de configura├º├úo: O Bucket de imagens n├úo existe. Contate o suporte.');
                }
                throw uploadErr;
            }

            // 5. Get Public URL
            const { data } = supabase.storage
                .from('family-photos')
                .getPublicUrl(filePath);

            setPhotoUrl(data.publicUrl);
            setIsCropModalOpen(false);
            setSelectedImage(null);

        } catch (error: any) {
            console.error('Error uploading:', error);
            setUploadError(error.message || 'Erro ao processar e salvar imagem.');
        } finally {
            setUploading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        // 1. Validation: Unique Root Member per Role
        if (role === 'patriarca' || role === 'matriarca') {
            const conflictingRoot = existingMembers.find(m =>
                m.role === role &&
                m.id !== member?.id
            );

            if (conflictingRoot) {
                alert(`Erro: J├í existe um(a) ${role === 'patriarca' ? 'Patriarca' : 'Matriarca'} cadastrado: ${conflictingRoot.name}.`);
                return;
            }
        }

        setLoading(true);

        const memberData = {
            name,
            parent_id: parentId || null,
            role,
            description,
            birth_date: birthDate || null,
            is_deceased: isDeceased,
            death_date: isDeceased ? (deathDate || null) : null,
            photo_url: photoUrl,
            social_links: {
                instagram,
                whatsapp,
                facebook
            }
        };

        try {
            if (member?.id) {
                // Update
                const { error } = await supabase
                    .from('family_members')
                    .update(memberData)
                    .eq('id', member.id);
                if (error) throw error;
            } else {
                // Insert
                const { error } = await supabase
                    .from('family_members')
                    .insert([memberData]);
                if (error) throw error;
            }
            onSuccess();
        } catch (error) {
            console.error('Error saving member:', error);
            alert('Erro ao salvar membro. Verifique o console.');
        } finally {
            setLoading(false);
        }
    };

    // Filter root couple for the "Genearcas" option
    const patriarch = existingMembers.find(m => m.role === 'patriarca');
    const matriarch = existingMembers.find(m => m.role === 'matriarca');

    // Parent options excluding roots (handled separately) and self
    const descParentOptions = existingMembers.filter(m =>
        m.role === 'descendente' &&
        m.id !== member?.id
    );

    return (
        <>
            <form onSubmit={handleSubmit} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Nome Completo</label>
                            <input
                                required
                                type="text"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-rosa-antigo outline-none"
                                placeholder="Ex: Maria Costa"
                            />
                        </div>

                        <div className="flex gap-4">
                            <div className="w-1/2">
                                <label className="block text-sm font-medium text-gray-700 mb-1">Papel na Fam├¡lia</label>
                                <select
                                    required
                                    value={role}
                                    onChange={(e) => setRole(e.target.value as any)}
                                    className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-rosa-antigo outline-none bg-white"
                                >
                                    <option value="descendente">Descendente</option>
                                    <option value="patriarca">Patriarca (Fundador)</option>
                                    <option value="matriarca">Matriarca (Fundadora)</option>
                                </select>
                            </div>
                            <div className="w-1/2">
                                <label className="block text-sm font-medium text-gray-700 mb-1">Filho(a) de quem?</label>
                                <select
                                    disabled={role !== 'descendente'}
                                    value={parentId}
                                    onChange={(e) => setParentId(e.target.value)}
                                    className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-rosa-antigo outline-none bg-white disabled:bg-gray-50 disabled:text-gray-400"
                                >
                                    <option value="">-- Raiz da Fam├¡lia --</option>
                                    {(patriarch || matriarch) && (
                                        <option value={patriarch?.id || matriarch?.id}>
                                            Genearcas (Raiz)
                                        </option>
                                    )}
                                    {descParentOptions.map((p) => (
                                        <option key={p.id} value={p.id}>{p.name}</option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Data de Nascimento</label>
                            <input
                                type="date"
                                value={birthDate}
                                onChange={(e) => setBirthDate(e.target.value)}
                                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-rosa-antigo outline-none"
                            />
                        </div>

                        <div className="bg-gray-50 p-3 rounded-lg border border-gray-100">
                            <label className="flex items-center gap-2 cursor-pointer mb-2">
                                <input
                                    type="checkbox"
                                    checked={isDeceased}
                                    onChange={(e) => setIsDeceased(e.target.checked)}
                                    className="rounded text-rosa-forte focus:ring-rosa-forte"
